<?php
namespace App\Console\Commands;
use App\Models\User;use Illuminate\Console\Command;use Illuminate\Support\Facades\Hash;use Illuminate\Support\Str;
class CreateBhudevSetuAdmin extends Command { protected $signature='digitalbhudev:create-admin {email} {--name=Administrator}'; protected $description='Create the first DigitalBhudev administrator (interactive password, no default credentials).'; public function handle(): int {$email=strtolower((string)$this->argument('email'));if(User::where('role','admin')->exists()){$this->error('An administrator already exists.');return self::FAILURE;}if(User::where('email',$email)->exists()){$this->error('That email is already registered.');return self::FAILURE;}$password=$this->secret('Admin password (minimum 12 characters)');if(strlen((string)$password)<12){$this->error('Password must be at least 12 characters.');return self::FAILURE;}$confirmation=$this->secret('Confirm admin password');if(!hash_equals((string)$password,(string)$confirmation)){$this->error('Passwords do not match.');return self::FAILURE;}User::create(['name'=>$this->option('name'),'email'=>$email,'password'=>Hash::make($password),'role'=>'admin','is_active'=>true,'email_verified_at'=>now()]);$this->info('Administrator created. Store the credentials securely.');return self::SUCCESS;} }
